import{_ as t,o,c as r,a0 as s}from"./chunks/framework.BdKrsJIB.js";const p=JSON.parse('{"title":"Boundary with tamias and peregrin","description":"","frontmatter":{},"headers":[],"relativePath":"explanation/boundary.md","filePath":"explanation/boundary.md"}'),a={name:"explanation/boundary.md"};function i(n,e,d,c,l,h){return o(),r("div",null,[...e[0]||(e[0]=[s('<h1 id="boundary-with-tamias-and-peregrin" tabindex="-1">Boundary with tamias and peregrin <a class="header-anchor" href="#boundary-with-tamias-and-peregrin" aria-label="Permalink to &quot;Boundary with tamias and peregrin&quot;">​</a></h1><p>tarsi owns <strong>release semantics</strong> — changelog → bump → tag → publish. Its neighbors own the layers around it:</p><table tabindex="0"><thead><tr><th>neighbor</th><th>owns</th><th>tarsi&#39;s relation</th></tr></thead><tbody><tr><td><strong>tamias</strong></td><td>content distribution — fetch, store, cache, dispense; <code>type:</code> content drivers</td><td>release <em>profiles</em> are <code>type: tarsi</code> packs; <code>tamias-driver-tarsi</code> validates/installs them; the <code>tarsi-serve</code> binary itself ships as a <code>type: files</code> pack (<code>libraries/tarsi</code>)</td></tr><tr><td><strong>peregrin</strong></td><td>orchestration — campaigns, multi-machine workflows</td><td><code>libraries/release</code> bundle drives <code>tarsi-serve release --yes</code>; campaigns call the same ndjson ops humans and agents use</td></tr><tr><td><strong>lasius</strong></td><td>git &amp; workspace expertise — <code>lasius-vcs</code> port</td><td>all history/tag/push goes through <code>lasius-vcs</code> + <code>lasius-vcs-git</code>; <code>tarsi-core</code> never touches git</td></tr><tr><td><strong>sepia</strong></td><td>session lifecycle</td><td>optional changelog polish — the caller may prompt a sepia session with rendered notes; no in-repo LLM path</td></tr><tr><td><strong>cuora</strong></td><td>secrets broker</td><td><code>token_env</code> names resolve through env/cuora; values never enter config, manifests, or logs</td></tr><tr><td><strong>scarab</strong></td><td>config/template expertise</td><td><code>tarsi.toml</code> discovery/layering is <code>scarab-config</code>&#39;s <code>FileSource</code>/<code>LayeredFileSource</code>; tarsi-config is only the wiring</td></tr><tr><td><strong>hypha</strong></td><td>distributed substrate</td><td><code>hypha-serve-cli</code> is the shared one-shot arg→params shim every <code>*-serve</code> bin uses</td></tr></tbody></table><h2 id="what-tarsi-is-not" tabindex="-1">What tarsi is not <a class="header-anchor" href="#what-tarsi-is-not" aria-label="Permalink to &quot;What tarsi is not&quot;">​</a></h2><ul><li><strong>Not a CLI.</strong> No <code>tarsi</code> binary, no verb tree — the surface is ops. (The legacy TypeScript changelog CLI under the README&#39;s bottom half is pre-rewrite reference only.)</li><li><strong>Not an orchestrator.</strong> <code>tarsi-serve</code> composes ports and answers ops; scheduling, approval flows, and UI live in peregrin/pavo.</li><li><strong>Not a publisher of record for the org.</strong> Org repos release tag-only; crates.io publishing is tamias-only and GitHub Releases are unused (ADR-0004). The <code>tarsi-publish-*</code> crates exist for external consumers who opt back in per-repo.</li><li><strong>Not a registry.</strong> It reads git history and writes tags/manifests; it does not host anything.</li></ul><h2 id="the-dogfooding-loop" tabindex="-1">The dogfooding loop <a class="header-anchor" href="#the-dogfooding-loop" aria-label="Permalink to &quot;The dogfooding loop&quot;">​</a></h2><p><code>tarsi</code>&#39;s own <code>tarsi.toml</code> configures its release — units resolve from the cargo workspace, <code>tarsi-xtask</code> is skipped, both publish targets are off. Releasing tarsi itself is plan F of PL-014: a human or campaign decision, never an agent&#39;s.</p>',7)])])}const u=t(a,[["render",i]]);export{p as __pageData,u as default};
